#include <iostream>
#include <vector>
using namespace std;

int binarySearch(vector<int>& arr, int target) {
    int left = 0;
    int right = arr.size() - 1;

    while (left <= right) {
        int mid = left + (right - left) / 2;  // safe mid calculation

        if (arr[mid] == target) {
            return mid;       // found
        }
        else if (arr[mid] < target) {
            left = mid + 1;   // go right half
        }
        else {
            right = mid - 1;  // go left half
        }
    }

    return -1;  // not found
}

int main() {
    vector<int> arr = {3, 7, 11, 15, 19, 23, 27, 31};

    cout << binarySearch(arr, 23) << endl;  // 5
    cout << binarySearch(arr, 10) << endl;  // -1

    return 0;
}

