def binary_search(arr, target):
    left = 0
    right = len(arr) - 1

    while left <= right:
        mid = left + (right - left) // 2  # safe mid calculation

        if arr[mid] == target:
            return mid  # found
        elif arr[mid] < target:
            left = mid + 1  # go right half
        else:
            right = mid - 1  # go left half

    return -1  # not found


if __name__ == "__main__":
    arr = [3, 7, 11, 15, 19, 23, 27, 31]

    print(binary_search(arr, 23))  # 5
    print(binary_search(arr, 10))  # -1
